function norm(value){return String(value??'').replace(/\s+/g,' ').trim();}
export function getLocale(){const value=localStorage.getItem(STORAGE);return LOCALES.includes(value)?value:'ru';}
export function tr(source,locale=getLocale()){
 if(locale==='ru')return String(source??'');
 const row=P[norm(source)];return row?.[IDX[locale]]||String(source??'');
}
export function setLocale(locale){if(!LOCALES.includes(locale))return;localStorage.setItem(STORAGE,locale);document.documentElement.lang=locale;window.dispatchEvent(new CustomEvent('syolana:locale',{detail:{locale}}));}
export function locales(){return [...LOCALES];}
export function languageName(locale){return {ru:'Русский',en:'English',es:'Español',fr:'Français'}[locale]||locale;}
export function localeCode(locale=getLocale()){return locale.toUpperCase();}
export function metaFor(locale=getLocale()){
 const data={
  ru:{title:'Syolana · Живые темы, шаблоны и языки',description:'Syolana — дизайн-система для живых сайтов и авторские языковые курсы. Готовый HTML-файл, ваш хостинг и ваш домен. Полный английский A1 бесплатно.'},
  en:{title:'Syolana · Living themes, templates and languages',description:'Syolana is a design system for living websites and original language courses. One ready HTML file, your hosting and your domain. Complete English A1 is free.'},
  es:{title:'Syolana · Temas vivos, plantillas e idiomas',description:'Syolana es un sistema de diseño para sitios vivos y cursos de idiomas de autor. Un archivo HTML listo, tu alojamiento y tu dominio. Inglés A1 completo gratis.'},
  fr:{title:'Syolana · Thèmes vivants, modèles et langues',description:'Syolana est un système de design pour sites vivants et des cours de langues d’auteur. Un fichier HTML prêt, votre hébergement et votre domaine. Anglais A1 complet gratuit.'}
 };return data[locale]||data.ru;
}
